create table xxcus.xxfnd_sod_rules (
    sod_rule_id           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    role_code_1           varchar2(30 byte) not null enable,
    role_code_2           varchar2(30 byte) not null enable,
    conflict_scope        varchar2(30 byte) not null enable,
    description           varchar2(500 byte),
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_sod_rules add constraint xxfnd_sod_rules_ck1 check ( role_code_1 < role_code_2 ) enable;

alter table xxcus.xxfnd_sod_rules
    add constraint xxfnd_sod_rules_ck2
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_sod_rules
    add constraint xxfnd_sod_rules_pk primary key ( sod_rule_id )
        using index enable;

alter table xxcus.xxfnd_sod_rules
    add constraint xxfnd_sod_rules_uk1
        unique ( role_code_1,
                 role_code_2,
                 conflict_scope )
            using index enable;


